  "No platform covers everything, and none of them reads itself. We run five, with the search, press and AI tools around them, and pick what fits the question.": "Aucune plateforme ne couvre tout, et aucune ne se lit toute seule. Nous en exploitons cinq, avec les outils de recherche, de presse et d'IA qui les entourent, et choisissons ce qui répond à la question.",
  "The broadest coverage on the market: volume, topics and sentiment across languages, read over long periods.": "La couverture la plus large du marché : volumes, sujets et sentiment dans toutes les langues, lus sur de longues périodes.",
  "Best for": "Idéal pour",
  "Brand health over time": "La santé de marque dans la durée",
  "Crisis and real-time alerts": "Les crises et les alertes en temps réel",
  "Visual and product presence": "La présence visuelle et produit",
  "Who the communities actually are: interests, affinities and overlaps, at the detail a persona needs.": "Qui sont vraiment les communautés : centres d'intérêt, affinités et recoupements, au niveau de détail d'un persona.",
  "Audiences and segmentation": "Les audiences et la segmentation",
  "Where the signal comes from": "D'où vient le signal",
  "Collect, qualify, decide.": "Collecter, qualifier, décider.",
  "The platforms collect; our proprietary algorithms qualify; consultants decide what is signal.": "Les plateformes collectent, nos algorithmes propriétaires qualifient, les consultants décident de ce qui fait signal.",
  "Collect": "Collecter",
  "Five platforms, 22 networks, search, press and generative AI.": "Cinq plateformes, 22 réseaux, la recherche, la presse et l'IA générative.",
  "Qualify": "Qualifier",
  "Our algorithms profile users on their interactions, behaviour and content consumption.": "Nos algorithmes profilent les utilisateurs selon leurs interactions, leur comportement et leurs contenus.",
  "3 bn": "3 Md",
  "users profiled daily · 5,000+ criteria": "utilisateurs profilés chaque jour · 5 000+ critères",
  "Decide": "Décider",
  "An analyst reads it, in the language of the market, and tells you what to do.": "Un analyste le lit, dans la langue du marché, et vous dit quoi faire.",
  "Leave your email or phone number. A consultant calls you back within 30 minutes on weekdays and tells you which sources we would use, and what they cannot tell you.": "Laissez votre e-mail ou votre téléphone. Un consultant vous rappelle dans les 30 minutes en semaine et vous dit quelles sources nous utiliserions, et ce qu'elles ne peuvent pas vous dire.",
  "The four layers": "Les quatre calques",
  "The whole Licter team in the office, standing and seated around a coffee table": "Toute l'équipe Licter au bureau, debout et assise autour d'une table basse",
  "A Licter consultant in an armchair, an open laptop in hand": "Un membre de l'équipe Licter dans un fauteuil, un ordinateur ouvert à la main",
  "Two Licter consultants framing a question at a table, a laptop between them": "Deux membres de l'équipe Licter cadrent une question à table, un ordinateur entre eux",
  "Two Licter consultants going through a collection on a laptop, on a sofa": "Deux membres de l'équipe Licter passent en revue une collecte sur un ordinateur, dans un canapé",
  "Three Licter consultants reading an analysis together on a laptop": "Trois membres de l'équipe Licter lisent une analyse ensemble sur un ordinateur",
