  "The texts, photographs, videos and logos on this site belong to Licter or are used with the permission of their owners. They may not be reused without prior written consent.": "Les textes, photographies, vidéos et logos de ce site appartiennent à Licter ou sont utilisés avec l'accord de leurs titulaires. Ils ne peuvent être réutilisés sans autorisation écrite préalable.",
  "Team photographs: [photographer or agency, with permission].": "Photos de l'équipe : [photographe ou agence, avec autorisation].",
  "PRIVACY": "CONFIDENTIALITÉ",
