  "PLAINLY.": "SIMPLEMENT.",
  "What we collect when you fill in a form, why, and how to have it deleted.": "Ce que nous collectons quand vous remplissez un formulaire, pourquoi, et comment le faire supprimer.",
  "What we collect": "Ce que nous collectons",
  "Why": "Pourquoi",
