  "11,400": "11 400",
  "posts read in three weeks, across four markets and four languages": "publications lues en trois semaines, sur quatre marchés et dans quatre langues",
  "A food group was about to change the recipe of its best seller.": "Un groupe agroalimentaire s'apprêtait à changer la recette de son best-seller.",
  "The question": "La question",
  "What the data said": "Ce que disait la donnée",
  "What they changed": "Ce qu'ils ont changé",
  "Sales were down and the surveys blamed the taste. Should they reformulate?": "Les ventes baissaient et les études accusaient le goût. Fallait-il reformuler ?",
  "Nobody was complaining about the taste. People were angry about the new, smaller pack, and said so in posts no survey had asked about.": "Personne ne se plaignait du goût. Les gens en voulaient au nouveau format, plus petit, et le disaient dans des publications qu'aucune étude n'avait sollicitées.",
  "They kept the recipe, brought the old pack back in two markets, and sales recovered within a quarter.": "Ils ont gardé la recette, rétabli l'ancien format sur deux marchés, et les ventes sont reparties en un trimestre.",
  "For insights and marketing teams": "Pour les équipes insights et marketing",
  "For communication and risk teams": "Pour les équipes communication et risques",
  "For teams that already own a platform": "Pour les équipes qui ont déjà une plateforme",
